package com.bank.longestvalid;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.Logger;

// Finds the longest balanced grouping run for National Bank of India salvage parsing.
public class LongestValidFinder {
    private static final Logger log = Logger.getLogger(LongestValidFinder.class.getName());

    // Longest valid parentheses via stack of indices. O(n), O(n).
    public int longestValid(String markers) {
        if (markers == null) {
            throw new IllegalArgumentException("markers must not be null");
        }
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);                              // base: last invalid position
        int best = 0;
        for (int i = 0; i < markers.length(); i++) {
            if (markers.charAt(i) == '(') {
                stack.push(i);                       // remember opener's index
            } else {
                stack.pop();                         // pair off the matching opener
                if (stack.isEmpty()) {
                    stack.push(i);                   // unmatched closer → new base
                } else {
                    int len = i - stack.peek();      // run back to enclosing boundary
                    if (len > best) {
                        best = len;
                    }
                }
            }
        }
        final int result = best;
        log.info(() -> "Longest valid run = " + result);
        return best;
    }
}
