package com.bank.longestvalid;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: longest balanced grouping run.
public class LongestValidDemo {
    private static final Logger log = Logger.getLogger(LongestValidDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        LongestValidFinder finder = new LongestValidFinder();

        log.info(() -> "Run = " + finder.longestValid("(()"));      // 2
        log.info(() -> "Run = " + finder.longestValid(")()())"));   // 4
        log.info(() -> "Run = " + finder.longestValid(""));         // 0
    }
}
